package main

import (
	"encoding/json"
	"fmt"
	"os"
	"regexp"
	"strings"
)

var nameRe = regexp.MustCompile(`^[a-z][a-z0-9_-]{0,63}$`)

type Manifest struct {
	Name      string                 `json:"name"`
	Version   string                 `json:"version"`
	Verify    VerifyConfig           `json:"verification"`
	Env       EnvironmentConfig      `json:"environment"`
	Steps     []Step                 `json:"steps"`
	Refs      map[string]string      `json:"references"`
}

type VerifyConfig struct {
	Passes    int    `json:"passes"`
	Algorithm string `json:"algorithm"`
	Mode      string `json:"mode"`
}

type EnvironmentConfig struct {
	Locale              string            `json:"locale"`
	Timezone            string            `json:"timezone"`
	Seed                *int              `json:"seed"`
	EnvVars             map[string]string `json:"env_vars"`
	BlockedEnvVars      []string          `json:"blocked_env_vars"`
	NormalizePaths      bool              `json:"normalize_paths"`
	NormalizeTimestamps bool             `json:"normalize_timestamps"`
}

type Step struct {
	ID            string            `json:"id"`
	Command       string            `json:"command"`
	WorkingDir    string            `json:"working_dir"`
	Inputs        []string          `json:"inputs"`
	Outputs       []string          `json:"outputs"`
	DependsOn     []string          `json:"depends_on"`
	TimeoutSecs   int               `json:"timeout_seconds"`
	EnvOverrides  map[string]string `json:"env_overrides"`
}

func loadManifest(path string) (*Manifest, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, fmt.Errorf("manifest not found: %s", path)
		}
		return nil, err
	}

	raw := map[string]json.RawMessage{}
	if err := json.Unmarshal(data, &raw); err != nil {
		return nil, fmt.Errorf("invalid manifest JSON: %s", err.Error())
	}
	for _, field := range []string{"name", "version", "verification", "environment", "steps"} {
		if _, ok := raw[field]; !ok {
			return nil, fmt.Errorf("missing required field: %s", field)
		}
	}

	var m Manifest
	if err := json.Unmarshal(data, &m); err != nil {
		return nil, fmt.Errorf("invalid manifest JSON: %s", err.Error())
	}

	if m.Name == "" {
		return nil, fmt.Errorf("missing required field: name")
	}
	if !nameRe.MatchString(m.Name) {
		return nil, fmt.Errorf("invalid name format: %q (must match ^[a-z][a-z0-9_-]{0,63}$)", m.Name)
	}
	if m.Version == "" {
		return nil, fmt.Errorf("missing required field: version")
	}

	vraw := map[string]json.RawMessage{}
	if err := json.Unmarshal(raw["verification"], &vraw); err != nil {
		return nil, fmt.Errorf("invalid manifest JSON: %s", err.Error())
	}
	for _, field := range []string{"passes", "algorithm", "mode"} {
		if _, ok := vraw[field]; !ok {
			return nil, fmt.Errorf("missing required field: verification.%s", field)
		}
	}
	switch m.Verify.Algorithm {
	case "sha256", "blake2b":
	default:
		return nil, fmt.Errorf("invalid algorithm: %q (must be \"sha256\" or \"blake2b\")", m.Verify.Algorithm)
	}
	switch m.Verify.Mode {
	case "full", "incremental", "targeted":
	default:
		return nil, fmt.Errorf("invalid mode: %q (must be \"full\", \"incremental\", or \"targeted\")", m.Verify.Mode)
	}
	if m.Verify.Passes < 1 {
		return nil, fmt.Errorf("passes must be >= 1, got %d", m.Verify.Passes)
	}

	if m.Env.Locale == "" {
		m.Env.Locale = "C"
	}
	if m.Env.Timezone == "" {
		m.Env.Timezone = "UTC"
	}
	if m.Env.EnvVars == nil {
		m.Env.EnvVars = map[string]string{}
	}
	if m.Env.BlockedEnvVars == nil {
		m.Env.BlockedEnvVars = []string{}
	}

	if len(m.Steps) == 0 {
		return nil, fmt.Errorf("steps must contain at least one step")
	}
	stepIDs := map[string]bool{}
	for i, s := range m.Steps {
		if s.ID == "" {
			return nil, fmt.Errorf("missing required field: steps[%d].id", i)
		}
		if !nameRe.MatchString(s.ID) {
			return nil, fmt.Errorf("invalid step id: %q (must match ^[a-z][a-z0-9_-]{0,63}$)", s.ID)
		}
		if stepIDs[s.ID] {
			return nil, fmt.Errorf("duplicate step id: %q", s.ID)
		}
		stepIDs[s.ID] = true
		if s.Command == "" {
			return nil, fmt.Errorf("missing required field: steps[%d].command", i)
		}
		if s.WorkingDir == "" {
			s.WorkingDir = "."
		}
		if s.TimeoutSecs <= 0 {
			s.TimeoutSecs = 300
		}
		if s.Inputs == nil {
			s.Inputs = []string{}
		}
		if s.Outputs == nil {
			s.Outputs = []string{}
		}
		if s.DependsOn == nil {
			s.DependsOn = []string{}
		}
		if s.EnvOverrides == nil {
			s.EnvOverrides = map[string]string{}
		}
		m.Steps[i] = s
	}

	for _, s := range m.Steps {
		for _, dep := range s.DependsOn {
			if !stepIDs[dep] {
				return nil, fmt.Errorf("unknown dependency: step %q depends on %q", s.ID, dep)
			}
		}
	}

	if cyc := shortestCycle(m.Steps); len(cyc) > 0 {
		return nil, fmt.Errorf("cycle detected: %s", strings.Join(cyc, " -> "))
	}
	return &m, nil
}
EOF

