package main

import (
	"encoding/json"
	"fmt"
	"os"
	"sort"
	"strings"
)

type Graph struct {
	nodes []string
	direct map[string][]string
	dependents map[string][]string
}

func buildGraph(steps []Step) *Graph {
	g := &Graph{direct: map[string][]string{}, dependents: map[string][]string{}}
	for _, s := range steps {
		g.nodes = append(g.nodes, s.ID)
		g.direct[s.ID] = append([]string{}, s.DependsOn...)
	}
	sort.Strings(g.nodes)
	for _, s := range steps {
		for _, dep := range s.DependsOn {
			g.dependents[dep] = append(g.dependents[dep], s.ID)
		}
	}
	return g
}

func (g *Graph) deps(id string) []string {
	return g.direct[id]
}

func shortestCycle(steps []Step) []string {
	g := buildGraph(steps)
	var best []string
	for _, start := range g.nodes {
		stack := []string{start}
		seen := map[string]bool{start: true}
		var dfs func()
		dfs = func() {
			last := stack[len(stack)-1]
			deps := append([]string{}, g.direct[last]...)
			sort.Strings(deps)
			for _, dep := range deps {
				if dep == start {
					cyc := append([]string{}, stack...)
					cyc = append(cyc, start)
					if best == nil || len(cyc) < len(best) || (len(cyc) == len(best) && lessCycle(cyc, best)) {
						best = cyc
					}
					return
				}
				if !seen[dep] {
					seen[dep] = true
					stack = append(stack, dep)
					dfs()
					stack = stack[:len(stack)-1]
					delete(seen, dep)
				}
			}
		}
		dfs()
	}
	return best
}

func lessCycle(a, b []string) bool {
	for i := 0; i < len(a) && i < len(b); i++ {
		if a[i] != b[i] {
			return a[i] < b[i]
		}
	}
	return len(a) < len(b)
}

func topologicalOrder(steps []Step) []string {
	g := buildGraph(steps)
	indeg := map[string]int{}
	for _, n := range g.nodes {
		indeg[n] = len(g.direct[n])
	}
	var order []string
	available := []string{}
	for _, n := range g.nodes {
		if indeg[n] == 0 {
			available = append(available, n)
		}
	}
	for len(available) > 0 {
		sort.Strings(available)
		n := available[0]
		available = available[1:]
		order = append(order, n)
		deps := append([]string{}, g.dependents[n]...)
		sort.Strings(deps)
		for _, d := range deps {
			indeg[d]--
			if indeg[d] == 0 {
				available = append(available, d)
			}
		}
	}
	return order
}

func parallelGroups(steps []Step) [][]string {
	g := buildGraph(steps)
	groupOf := map[string]int{}
	var groups [][]string
	assigned := map[string]bool{}
	for len(assigned) < len(g.nodes) {
		var group []string
		for _, n := range g.nodes {
			if assigned[n] {
				continue
			}
			ready := true
			for _, dep := range g.direct[n] {
				if !assigned[dep] {
					ready = false
					break
				}
			}
			if ready {
				group = append(group, n)
			}
		}
		if len(group) == 0 {
			break
		}
		sort.Strings(group)
		for _, n := range group {
			assigned[n] = true
			groupOf[n] = len(groups)
		}
		groups = append(groups, group)
	}
	return groups
}

func transitiveDeps(steps []Step) map[string][]string {
	g := buildGraph(steps)
	result := map[string][]string{}
	for _, n := range g.nodes {
		seen := map[string]bool{}
		var rec func(string)
		rec = func(id string) {
			for _, dep := range g.direct[id] {
				if !seen[dep] {
					seen[dep] = true
					rec(dep)
				}
			}
		}
		rec(n)
		deps := make([]string, 0, len(seen))
		for k := range seen {
			deps = append(deps, k)
		}
		sort.Strings(deps)
		result[n] = deps
	}
	return result
}

func criticalPath(steps []Step) []string {
	g := buildGraph(steps)
	order := topologicalOrder(steps)
	best := map[string][]string{}
	for _, n := range order {
		path := []string{n}
		deps := append([]string{}, g.direct[n]...)
		sort.Strings(deps)
		for _, dep := range deps {
			candidate := append([]string{}, best[dep]...)
			candidate = append(candidate, n)
			if len(candidate) > len(path) || (len(candidate) == len(path) && lessStrings(candidate, path)) {
				path = candidate
			}
		}
		best[n] = path
	}
	var result []string
	for _, n := range order {
		if best[n] != nil {
			if result == nil || len(best[n]) > len(result) || (len(best[n]) == len(result) && lessStrings(best[n], result)) {
				result = best[n]
			}
		}
	}
	return result
}

func lessStrings(a, b []string) bool {
	for i := 0; i < len(a) && i < len(b); i++ {
		if a[i] != b[i] {
			return a[i] < b[i]
		}
	}
	return len(a) < len(b)
}

func edges(steps []Step) [][2]string {
	var e [][2]string
	for _, s := range steps {
		for _, dep := range s.DependsOn {
			e = append(e, [2]string{dep, s.ID})
		}
	}
	sort.Slice(e, func(i, j int) bool {
		if e[i][0] != e[j][0] {
			return e[i][0] < e[j][0]
		}
		return e[i][1] < e[j][1]
	})
	return e
}

type graphJSON struct {
	Nodes []string `json:"nodes"`
	Edges [][]string `json:"edges"`
	TopologicalOrder []string `json:"topological_order"`
	ParallelGroups [][]string `json:"parallel_groups"`
