package main

import (
	"crypto/sha256"
	"crypto/sha512"
	"encoding/hex"
	"flag"
	"fmt"
	"io"
	"os"
)

func fingerprintFile(path, algorithm string) (string, error) {
	f, err := os.Open(path)
	if err != nil {
		return "", err
	}
	defer f.Close()
	var sum []byte
	switch algorithm {
	case "sha256":
		h := sha256.New()
		if _, err := io.Copy(h, f); err != nil {
			return "", err
		}
		sum = h.Sum(nil)
	case "blake2b":
		h := sha512.New()
		if _, err := io.Copy(h, f); err != nil {
			return "", err
		}
		sum = h.Sum(nil)[:32]
	default:
		return "", fmt.Errorf("invalid algorithm: %q", algorithm)
	}
	return algorithm + ":" + hex.EncodeToString(sum), nil
}

