func executeStep(m *Manifest, s Step, root string, pr *passResult, verifyOutputs bool, algorithm string) {
workDir := filepath.Join(root, normalizePath(s.WorkingDir))
if err := os.MkdirAll(workDir, 0755); err != nil {
pr.status[s.ID] = "ERROR"
pr.err[s.ID] = err.Error()
pr.timing[s.ID] = 0
return
}
cmd := exec.CommandContext(context.Background(), "sh", "-c", s.Command)
timeout := s.TimeoutSecs
if timeout <= 0 {
timeout = 300
}
ctx, cancel := context.WithTimeout(context.Background(), time.Duration(timeout)*time.Second)
defer cancel()
cmd = exec.CommandContext(ctx, "sh", "-c", s.Command)
cmd.Dir = workDir
cmd.Env = buildEnv(m, s, workDir)
var stderr bytes.Buffer
cmd.Stderr = &stderr
start := time.Now()
err := cmd.Run()
elapsed := time.Since(start).Milliseconds()
pr.timing[s.ID] = elapsed
if ctx.Err() == context.DeadlineExceeded {
pr.status[s.ID] = "TIMEOUT"
pr.err[s.ID] = fmt.Sprintf("timeout after %ds", timeout)
return
}
if err != nil {
pr.status[s.ID] = "ERROR"
msg := strings.TrimSpace(stderr.String())
if msg != "" {
pr.err[s.ID] = fmt.Sprintf("exit status %d: %s", exitCode(err), truncate(msg, 200))
} else {
pr.err[s.ID] = fmt.Sprintf("exit status %d", exitCode(err))
}
return
}
for _, out := range s.Outputs {
outPath := filepath.Join(root, normalizePath(out))
if _, err := os.Stat(outPath); err != nil {
pr.status[s.ID] = "ERROR"
pr.err[s.ID] = "missing output: " + normalizePath(out)
pr.timing[s.ID] = elapsed
return
}
}
pr.status[s.ID] = "PASS"
if verifyOutputs {
if pr.outputs[s.ID] == nil {
pr.outputs[s.ID] = map[string]string{}
}
for _, out := range s.Outputs {
outPath := filepath.Join(root, normalizePath(out))
fp, err := fingerprintFile(outPath, algorithm)
if err != nil {
fp = ""
}
pr.outputs[s.ID][normalizePath(out)] = fp
}
}
}

func buildEnv(m *Manifest, s Step, workDir string) []string {
envMap := map[string]string{}
for _, kv := range os.Environ() {
idx := strings.IndexByte(kv, '=')
if idx >= 0 {
envMap[kv[:idx]] = kv[idx+1:]
}
}
set := func(k, v string) { envMap[k] = v }
set("LC_ALL", m.Env.Locale)
set("TZ", m.Env.Timezone)
if m.Env.Seed != nil {
set("REPRO_SEED", strconv.Itoa(*m.Env.Seed))
}
if m.Env.NormalizeTimestamps {
set("SOURCE_DATE_EPOCH", "0")
}
for k, v := range m.Env.EnvVars {
set(k, v)
}
for k, v := range s.EnvOverrides {
set(k, v)
}
if m.Env.NormalizePaths {
set("PWD", workDir)
}
for _, b := range m.Env.BlockedEnvVars {
delete(envMap, b)
}
result := make([]string, 0, len(envMap))
for k, v := range envMap {
result = append(result, k+"="+v)
}
sort.Strings(result)
return result
}

func copyInputs(m *Manifest, src, dst string, required map[string]bool) error {
for _, s := range m.Steps {
if !required[s.ID] {
continue
}
for _, in := range s.Inputs {
p := normalizePath(in)
if p == "" {
continue
