if p == "" {
continue
}
fp, err := fingerprintFile(filepath.Join(root, p), m.Verify.Algorithm)
if err != nil {
return false, nil, nil
}
currentInputs[p] = fp
}
cachedInputs := map[string]string{}
if data, err := os.ReadFile(filepath.Join(cacheStepDir, "inputs.json")); err == nil {
if err := json.Unmarshal(data, &cachedInputs); err != nil {
return false, nil, nil
}
} else {
return false, nil, nil
}
if !mapsEqual(currentInputs, cachedInputs) {
return false, nil, nil
}
cachedOutputs := map[string]string{}
if data, err := os.ReadFile(filepath.Join(cacheStepDir, "outputs.json")); err == nil {
if err := json.Unmarshal(data, &cachedOutputs); err != nil {
return false, nil, nil
}
} else {
return false, nil, nil
}
if len(cachedOutputs) == 0 && len(s.Outputs) > 0 {
return false, nil, nil
}
return true, cachedOutputs, nil
}

func writeCache(m *Manifest, s Step, root, cacheDir string, outputs map[string]string) {
cacheStepDir := filepath.Join(cacheDir, s.ID)
if err := os.MkdirAll(cacheStepDir, 0755); err != nil {
return
}
inputs := map[string]string{}
for _, in := range s.Inputs {
p := normalizePath(in)
if p == "" {
continue
}
if fp, err := fingerprintFile(filepath.Join(root, p), m.Verify.Algorithm); err == nil {
inputs[p] = fp
}
}
if data, err := json.MarshalIndent(inputs, "", "  "); err == nil {
os.WriteFile(filepath.Join(cacheStepDir, "inputs.json"), data, 0644)
}
if data, err := json.MarshalIndent(outputs, "", "  "); err == nil {
os.WriteFile(filepath.Join(cacheStepDir, "outputs.json"), data, 0644)
}
}

func buildReport(m *Manifest, passes []*passResult, topOrder []string, topoIndex map[string]int, trans map[string][]string, targetedSteps []string, required map[string]bool, targetSet map[string]bool) *report {
rep := &report{
ManifestName:    m.Name,
ManifestVersion: m.Version,
Timestamp:       time.Now().UTC().Format(time.RFC3339),
}
rep.VerificationConfig.Passes = m.Verify.Passes
rep.VerificationConfig.Algorithm = m.Verify.Algorithm
rep.VerificationConfig.Mode = m.Verify.Mode
if m.Verify.Mode == "targeted" {
rep.VerificationConfig.TargetedSteps = targetedSteps
}
rep.EnvironmentConfig.Locale = m.Env.Locale
rep.EnvironmentConfig.Timezone = m.Env.Timezone
rep.EnvironmentConfig.Seed = m.Env.Seed
rep.EnvironmentConfig.NormalizePaths = m.Env.NormalizePaths
rep.EnvironmentConfig.NormalizeTimestamps = m.Env.NormalizeTimestamps
rep.EnvironmentConfig.BlockedEnvVars = m.Env.BlockedEnvVars
pg := parallelGroups(m.Steps)
rep.DependencyAnalysis.TopologicalOrder = topOrder
rep.DependencyAnalysis.ParallelGroups = pg
rep.DependencyAnalysis.CriticalPath = criticalPath(m.Steps)
rep.DependencyAnalysis.TotalSteps = len(m.Steps)
rep.DependencyAnalysis.MaxParallelism = 0
for _, g := range pg {
if len(g) > rep.DependencyAnalysis.MaxParallelism {
rep.DependencyAnalysis.MaxParallelism = len(g)
}
}
stepByID := map[string]Step{}
for _, s := range m.Steps {
stepByID[s.ID] = s
}
for _, id := range topOrder {
s := stepByID[id]
sr := stepReport{
ID:            id,
ExecutionOrder: topoIndex[id],
TimingMs:      make([]int64, len(passes)),
}
for i, pr := range passes {
sr.TimingMs[i] = pr.timing[id]
}
if !required[id] {
sr.Status = "SKIPPED"
rep.Steps = append(rep.Steps, sr)
continue
}
anyError := false
anyTimeout := false
var firstErr string
for _, pr := range passes {
st := pr.status[id]
if st == "ERROR" {
anyError = true
if firstErr == "" {
firstErr = pr.err[id]
}
}
if st == "TIMEOUT" {
anyTimeout = true
if firstErr == "" {
firstErr = pr.err[id]
}
}
}
if anyTimeout {
sr.Status = "TIMEOUT"
if firstErr != "" {
msg := firstErr
sr.ErrorMessage = &msg
}
rep.Steps = append(rep.Steps, sr)
continue
}
if anyError {
sr.Status = "ERROR"
if firstErr != "" {
msg := firstErr
sr.ErrorMessage = &msg
}
rep.Steps = append(rep.Steps, sr)
continue
}
if targetSet[id] {
for _, out := range s.Outputs {
outKey := normalizePath(out)
outPath := reportPath(m, s, out)
fps := make([]string, len(passes))
for i, pr := range passes {
if pr.outputs[id] != nil {
fps[i] = pr.outputs[id][outKey]
}
}
consistent := allEqualNonEmpty(fps)
var ref *string
var refMatch *bool
if r, ok := m.Refs[outPath]; ok {
ref = &r
match := len(fps) > 0 && fps[0] == r
refMatch = &match
} else if r, ok := m.Refs[outKey]; ok {
ref = &r
match := len(fps) > 0 && fps[0] == r
refMatch = &match
}
var variance *string
if !consistent {
detail := "fingerprints differ across passes"
variance = &detail
}
sr.Outputs = append(sr.Outputs, outputReport{
Path:                outPath,
Fingerprints:        fps,
Reference:           ref,
ReferenceMatch:      refMatch,
CrossPassConsistent: consistent,
VarianceDetail:      variance,
})
}
bad := false
for _, o := range sr.Outputs {
if !o.CrossPassConsistent {
bad = true
break
}
if o.ReferenceMatch != nil && !*o.ReferenceMatch {
bad = true
break
}
}
if bad {
sr.Status = "FAIL"
} else {
sr.Status = "PASS"
}
} else {
sr.Status = "PASS"
}
rep.Steps = append(rep.Steps, sr)
}
for _, sr := range rep.Steps {
switch sr.Status {
case "PASS":
rep.Summary.StepsPassed++
case "FAIL":
rep.Summary.StepsFailed++
case "ERROR":
rep.Summary.StepsError++
case "SKIPPED":
rep.Summary.StepsSkipped++
case "TIMEOUT":
rep.Summary.StepsTimeout++
}
for _, o := range sr.Outputs {
rep.Summary.TotalOutputs++
if o.CrossPassConsistent {
rep.Summary.ConsistentOutputs++
} else {
rep.Summary.InconsistentOutputs++
}
if o.ReferenceMatch != nil {
if *o.ReferenceMatch {
rep.Summary.ReferenceMatches++
} else {
rep.Summary.ReferenceMismatches++
}
}
}
}
rep.NonDeterminismHints = buildHints(m, passes, rep.Steps, stepByID)
hasError := false
for _, sr := range rep.Steps {
if sr.Status == "ERROR" || sr.Status == "TIMEOUT" {
hasError = true
break
}
}
hasFail := rep.Summary.InconsistentOutputs > 0 || rep.Summary.ReferenceMismatches > 0
if hasError {
rep.OverallStatus = "ERROR"
} else if hasFail {
rep.OverallStatus = "FAIL"
} else {
rep.OverallStatus = "PASS"
}
return rep
}

func buildHints(m *Manifest, passes []*passResult, steps []stepReport, stepByID map[string]Step) []hint {
var hints []hint
for _, sr := range steps {
s := stepByID[sr.ID]
for _, o := range sr.Outputs {
if o.CrossPassConsistent {
continue
}
hints = append(hints, hint{
Output:   o.Path,
StepID:   sr.ID,
HintType: classifyHint(m, s, o, passes),
Detail:   "output varied across passes",
})
}
}
sort.Slice(hints, func(i, j int) bool {
if hints[i].StepID != hints[j].StepID {
return hints[i].StepID < hints[j].StepID
}
return hints[i].Output < hints[j].Output
})
return hints
}

func classifyHint(m *Manifest, s Step, o outputReport, passes []*passResult) string {
if len(passes) < 2 {
return "unknown"
}
outKey := normalizePath(o.Path)
if m.Env.NormalizePaths {
wd := normalizePath(s.WorkingDir)
if wd != "" && wd != "." && strings.HasPrefix(outKey, wd+"/") {
outKey = strings.TrimPrefix(outKey, wd+"/")
}
}
var b1, b2 []byte
if len(passes) > 0 && passes[0].outputs[s.ID] != nil {
if fp, ok := passes[0].outputs[s.ID][normalizePath(o.Path)]; ok && fp == "" {
return "unknown"
}
}
if len(passes) > 1 && passes[1].outputs[s.ID] != nil {
if fp, ok := passes[1].outputs[s.ID][normalizePath(o.Path)]; ok && fp == "" {
return "unknown"
}
}
root1 := passes[0].root
root2 := passes[1].root
b1, err1 := os.ReadFile(filepath.Join(root1, normalizePath(o.Path)))
b2, err2 := os.ReadFile(filepath.Join(root2, normalizePath(o.Path)))
if err1 != nil || err2 != nil {
return "unknown"
}
str1 := string(b1)
str2 := string(b2)
if m.Env.NormalizePaths && (strings.Contains(str1, root1) || strings.Contains(str2, root2)) {
return "path"
}
if timestampRe.MatchString(str1) || timestampRe.MatchString(str2) {
return "timestamp"
}
if m.Env.Seed != nil || strings.Contains(s.Command, "random") || strings.Contains(s.Command, "RANDOM") {
return "random"
}
if len(m.Env.BlockedEnvVars) > 0 {
return "environment"
}
return "unknown"
}

func allEqualNonEmpty(fps []string) bool {
if len(fps) == 0 {
return false
}
first := fps[0]
if first == "" {
return false
}
for _, fp := range fps[1:] {
if fp != first {
return false
}
}
return true
}

func mapsEqual(a, b map[string]string) bool {
if len(a) != len(b) {
return false
}
for k, v := range a {
if b[k] != v {
return false
}
}
return true
}

func exitCode(err error) int {
var exitErr *exec.ExitError
if errorsAs(err, &exitErr) {
return exitErr.ExitCode()
}
return 1
}

func truncate(s string, n int) string {
if len(s) <= n {
return s
}
return s[:n] + "..."
}

func normalizePath(p string) string {
if p == "" {
return ""
}
p = filepath.ToSlash(p)
p = filepath.Clean(p)
if p == "." {
return ""
}
return p
}

func reportPath(m *Manifest, s Step, out string) string {
p := normalizePath(out)
if m.Env.NormalizePaths {
wd := normalizePath(s.WorkingDir)
if wd != "" && wd != "." {
prefix := wd + "/"
if strings.HasPrefix(p, prefix) {
p = strings.TrimPrefix(p, prefix)
}
}
}
return p
}
